"""The map of Sinnoh behind the Pokédex's area page (GAME-153), the owner's choice of 2026-10-19: a map of Sinnoh on
Bulbapedia (not in the repo), scaled to the page's width and cropped to its 256x168 (a few rows of clouds off the top
and bottom), cut to at most 224 colours by a median cut and to the DS's 15-bit colours. dex_map_layout.py's routes go
over it. Written by `dex_map_art.py pack-map PICTURE.png`. Not Anvil's to license: anvil/public/LICENSE.md lists it
under what the MIT License doesn't cover.
"""
